This section contains the contents of the repository's files.'use server';

import { createSupabaseServerClient } from '@/lib/supabase/server';

import {
  adminAuditActionSchema,
  adminEntityTypeSchema,
  entityTypeToCategory,
  type AdminAuditAction,
  type AdminAuditLogPreferences,
  type AdminEntityType,
  type BarangaySettings,
  type Json,
} from '@barangayan/shared';

// ---------------------------------------------------------------------------
// Core insert helper
// ---------------------------------------------------------------------------

interface LogParams {
  action: AdminAuditAction;
  entityType: AdminEntityType;
  entityId?: string;
  entityLabel?: string;
  changes?: { before: Record<string, unknown>; after: Record<string, unknown> };
  metadata?: Record<string, unknown>;
  /**
   * Pass the caller's already-loaded `barangaySettings` to skip a DB round-trip.
   * Omit for infrequent events (login/logout) — the helper fetches settings itself.
   */
  barangaySettings?: BarangaySettings | null;
}

/**
 * Insert one row into admin_audit_log from a Server Action context.
 * The server session cookie identifies the acting admin; no admin_id/barangay_id
 * is accepted from the caller to prevent spoofing.
 *
 * Callers should pass `barangaySettings` from their own hook/context to avoid an
 * extra per-call DB read. If omitted, settings are fetched once internally.
 */
export async function logAdminAction({
  action,
  entityType,
  entityId,
  entityLabel,
  changes,
  metadata,
  barangaySettings,
}: LogParams): Promise<void> {
  // Validate enums — fail loudly in development.
  adminAuditActionSchema.parse(action);
  adminEntityTypeSchema.parse(entityType);

  const supabase = await createSupabaseServerClient();

  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return;

  // Fetch admin profile + barangay config in one query.
  const { data: profile } = await supabase
    .from('profiles')
    .select('barangay_id, full_name, barangays(config)')
    .eq('id', user.id)
    .maybeSingle();

  if (!profile?.barangay_id) return;

  // Resolve settings: use passed-in value, or parse from the fetched config.
  const config = barangaySettings
    ?? ((profile.barangays as { config?: BarangaySettings } | null)?.config ?? null);

  // Master on/off switch.
  if (config?.features?.enableAdminAuditLog === false) return;

  // Per-category filter (skip when prefs absent — default is to log everything).
  const prefs = config?.adminAuditLogPreferences as AdminAuditLogPreferences | undefined;
  if (prefs) {
    const category = entityTypeToCategory(entityType);
    if (!prefs.enabledCategories[category]) return;
  }

  await supabase.from('admin_audit_log').insert({
    barangay_id: profile.barangay_id,
    admin_id: user.id,
    action,
    entity_type: entityType,
    entity_id: entityId ?? null,
    entity_label: entityLabel ?? null,
    // JSON round-trip rather than a cast: `changes` is typed as Record<string, unknown>,
    // which isn't structurally a Json value (could hold undefined/functions/etc.) even
    // though at runtime it's always plain audit data — this guarantees what actually
    // reaches Postgres matches what TypeScript says was sent.
    changes: changes ? (JSON.parse(JSON.stringify(changes)) as Json) : null,
    // Always include admin_name so the notification bell can display who acted.
    // Caller-supplied metadata is spread last so it can override if needed.
    metadata: { admin_name: profile.full_name, ...(metadata ?? {}) },
  });
}

// ---------------------------------------------------------------------------
// Auth event helpers — called around sign-in / sign-out
// ---------------------------------------------------------------------------

/** Call server-side immediately after a successful admin login. */
export async function logAdminLogin(): Promise<void> {
  await logAdminAction({
    action: 'login',
    entityType: 'system',
    entityLabel: 'Admin login',
  });
}

/** Call before sign-out (after sign-out the session is gone and the insert would fail). */
export async function logAdminLogout(): Promise<void> {
  await logAdminAction({
    action: 'logout',
    entityType: 'system',
    entityLabel: 'Admin logout',
  });
}'use client';

import { AdminSelect } from '@/components/admin/dropdown/admin-select';

import { ContentFormActions } from '@/components/admin/content-create-panel';
import styles from '@/components/admin/content-forms.module.css';

import { announcementSchema, ANNOUNCEMENT_CATEGORY_META, ANNOUNCEMENT_CATEGORIES } from '@barangayan/shared';
import { useRouter } from 'next/navigation';
import { useState } from 'react';

import { logAdminAction } from '@/actions/admin-audit-actions';
import { beginAttempt, notify as toast } from '@/lib/notify';
import { createSupabaseBrowserClient } from '@/lib/supabase/client';
import { LoadingButtonContent } from '@/components/loading/loading-button-content';

const inputClass =
  'w-full rounded-lg border border-zinc-300 px-3 py-1.5 text-sm outline-none focus:border-[var(--accent)] dark:border-zinc-700 dark:bg-zinc-800';
const labelClass = 'mb-1 block text-xs font-medium text-zinc-500';

export function AnnouncementForm({ barangayId }: { barangayId: string }) {
  const router = useRouter();

  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [detailedDescription, setDetailedDescription] = useState('');
  const [category, setCategory] = useState<string>('general');
  const [imageUrl, setImageUrl] = useState('');
  const [publishedAt, setPublishedAt] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  async function handleSubmit(event: React.FormEvent) {
    const toastAttempt = beginAttempt('handleSubmit');
    try {
      event.preventDefault();
      setError(null);

      const result = announcementSchema.safeParse({
        title,
        body,
        detailed_description: detailedDescription || undefined,
        category,
        image_url: imageUrl || undefined,
        published_at: publishedAt ? new Date(publishedAt).toISOString() : undefined,
      });

      if (!result.success) {
        toast.error('Review the highlighted fields before continuing.', { id: toastAttempt });
        setError(result.error.issues[0]?.message ?? 'Invalid input');
        return;
      }

      setSubmitting(true);
      const supabase = createSupabaseBrowserClient();
      const { error: insertError } = await supabase.from('announcements').insert({
        barangay_id: barangayId,
        title: result.data.title,
        body: result.data.body,
        detailed_description: result.data.detailed_description || null,
        category: result.data.category,
        image_url: result.data.image_url || null,
        published_at: result.data.published_at ?? new Date().toISOString(),
      });
      setSubmitting(false);

      if (insertError) {
        setError(insertError.message);
        toast.error(`Failed to create announcement: ${insertError.message}`, { id: toastAttempt });
        return;
      }

      logAdminAction({
        action: 'create',
        entityType: 'announcement',
        entityLabel: result.data.title,
        metadata: {
          title: result.data.title,
          body: result.data.body,
          detailed_description: result.data.detailed_description ?? null,
          category: result.data.category,
          published_at: result.data.published_at ?? null,
        },
      }).catch(() => {});

      setTitle('');
      setBody('');
      setDetailedDescription('');
      setCategory('general');
      setImageUrl('');
      setPublishedAt('');
      toast.success(`Announcement published.`, { id: toastAttempt });
      router.refresh();

    } catch {
      toast.warning('The action could not be confirmed. Refresh the record before trying again.', { id: toastAttempt });
    } finally { setSubmitting(false); }
  }

  return (
    <form onSubmit={handleSubmit} className={`${styles.form} grid grid-cols-1 gap-5 sm:grid-cols-2`}>
      <label className="sm:col-span-2 text-sm">
        <span className={labelClass}>Title</span>
        <input
          className={inputClass}
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="e.g. Typhoon Advisory: Signal No. 2 Raised"
          required
        />
      </label>

      <label className="sm:col-span-2 text-sm">
        <span className={labelClass}>Body</span>
        <textarea
          className={inputClass}
          value={body}
          onChange={(e) => setBody(e.target.value)}
          rows={3}
          placeholder="Short summary shown on the announcement card (2 sentences or so)…"
          required
        />
      </label>

      <label className="sm:col-span-2 text-sm">
        <span className={labelClass}>Detailed Description (optional)</span>
        <textarea
          className={inputClass}
          value={detailedDescription}
          onChange={(e) => setDetailedDescription(e.target.value)}
          rows={4}
          placeholder="Full write-up shown when a resident taps the announcement for more detail…"
        />
      </label>

      <div className={styles.groupHeading}><h3>Publication</h3></div>

      <label className="text-sm">
        <span className={labelClass}>Category</span>
        <AdminSelect kind="announcement" className={inputClass} value={category} onValueChange={(nextValue) => setCategory(nextValue)}>
          {ANNOUNCEMENT_CATEGORIES.map((cat) => (
            <option key={cat} value={cat}>
              {ANNOUNCEMENT_CATEGORY_META[cat].label}
            </option>
          ))}
        </AdminSelect>
      </label>

      <label className="text-sm">
        <span className={labelClass}>Publish At (optional)</span>
        <input
          type="datetime-local"
          className={inputClass}
          value={publishedAt}
          onChange={(e) => setPublishedAt(e.target.value)}
        />
      </label>

      <div className={styles.groupHeading}><h3>Media</h3></div>

      <label className="text-sm">
        <span className={labelClass}>Image URL (optional)</span>
        <input
          className={inputClass}
          value={imageUrl}
          onChange={(e) => setImageUrl(e.target.value)}
          placeholder="https://…"
          type="url"
        />
      </label>

      {error ? <p role="alert" className="sm:col-span-2 text-sm text-red-600">{error}</p> : null}

      <ContentFormActions busy={submitting}>
        <button
          type="submit"
          disabled={submitting || !barangayId}
          className="rounded-full bg-[var(--accent)] px-5 py-1.5 text-sm font-semibold text-white disabled:opacity-50"
          aria-busy={submitting}>
          <LoadingButtonContent pending={submitting} pendingLabel="Publishing…">Publish Announcement</LoadingButtonContent>
        </button>
      </ContentFormActions>
    </form>
  );
}'use client';

import { ContentEditDialog } from '@/components/admin/content-edit-dialog';
import editStyles from '@/components/admin/content-edit-dialog.module.css';

import { AdminSelect } from '@/components/admin/dropdown/admin-select';

import styles from '@/components/admin/content-workspace.module.css';

import { announcementSchema, ANNOUNCEMENT_CATEGORY_META, ANNOUNCEMENT_CATEGORIES, type Tables } from '@barangayan/shared';
import { useRouter } from 'next/navigation';
import { useState } from 'react';

import { logAdminAction } from '@/actions/admin-audit-actions';
import { ConfirmButton } from '@/components/admin/confirm-button';
import { beginAttempt, notify as toast } from '@/lib/notify';
import { createSupabaseBrowserClient } from '@/lib/supabase/client';
import { LoadingButtonContent } from '@/components/loading/loading-button-content';

type Announcement = Tables<'announcements'>;

const inputClass =
  'w-full rounded-lg border border-zinc-300 px-3 py-1.5 text-sm outline-none focus:border-[var(--accent)] dark:border-zinc-700 dark:bg-zinc-800';
const labelClass = 'mb-1 block text-xs font-medium text-zinc-500';

/** Formats an ISO datetime string for display (e.g. "Aug 7, 2026, 9:00 AM"). */
function formatPublishedAt(iso: string): string {
  return new Intl.DateTimeFormat('en-PH', { dateStyle: 'medium', timeStyle: 'short' }).format(
    new Date(iso),
  );
}

export function AnnouncementRow({ announcement }: { announcement: Announcement }) {
  const router = useRouter();

  const [isEditing, setIsEditing] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [title, setTitle] = useState(announcement.title);
  const [body, setBody] = useState(announcement.body);
  const [detailedDescription, setDetailedDescription] = useState(announcement.detailed_description ?? '');
  const [category, setCategory] = useState(announcement.category);
  const [imageUrl, setImageUrl] = useState(announcement.image_url ?? '');

  function startEdit() {
    setTitle(announcement.title);
    setBody(announcement.body);
    setDetailedDescription(announcement.detailed_description ?? '');
    setCategory(announcement.category);
    setImageUrl(announcement.image_url ?? '');
    setError(null);
    setIsEditing(true);
  }

  async function handleSave(event: React.FormEvent) {
    const toastAttempt = beginAttempt('handleSave');
    try {
      event.preventDefault();
      setError(null);

      const result = announcementSchema.safeParse({
        title,
        body,
        detailed_description: detailedDescription || undefined,
        category,
        image_url: imageUrl || undefined,
      });

      if (!result.success) {
        toast.error('Review the highlighted fields before continuing.', { id: toastAttempt });
        setError(result.error.issues[0]?.message ?? 'Invalid input');
        return;
      }

      setSubmitting(true);
      const supabase = createSupabaseBrowserClient();
      const { error: updateError } = await supabase
        .from('announcements')
        .update({
          title: result.data.title,
          body: result.data.body,
          detailed_description: result.data.detailed_description || null,
          category: result.data.category,
          image_url: result.data.image_url || null,
        })
        .eq('id', announcement.id);
      setSubmitting(false);

      if (updateError) {
        setError(updateError.message);
        toast.error(`Failed to save: ${updateError.message}`, { id: toastAttempt });
        return;
      }

      logAdminAction({
        action: 'update',
        entityType: 'announcement',
        entityId: announcement.id,
        entityLabel: result.data.title,
        changes: {
          before: {
            title: announcement.title,
            body: announcement.body,
            detailed_description: announcement.detailed_description,
            category: announcement.category,
          },
          after: {
            title: result.data.title,
            body: result.data.body,
            detailed_description: result.data.detailed_description || null,
            category: result.data.category,
          },
        },
      }).catch(() => {});

      toast.success('Announcement updated.', { id: toastAttempt });
      setIsEditing(false);
      router.refresh();

    } catch {
      toast.warning('The action could not be confirmed. Refresh the record before trying again.', { id: toastAttempt });
    } finally { setSubmitting(false); }
  }

  async function archive() {
    const toastAttempt = beginAttempt('archive');
    try {
      const supabase = createSupabaseBrowserClient();
      const { error: archiveError } = await supabase
        .from('announcements')
        .update({ deleted_at: new Date().toISOString() })
        .eq('id', announcement.id);
      if (archiveError) {
        toast.error(`Failed to archive: ${archiveError.message}`, { id: toastAttempt });
        return;
      }

      logAdminAction({
        action: 'delete',
        entityType: 'announcement',
        entityId: announcement.id,
        entityLabel: announcement.title,
        metadata: { title: announcement.title, body: announcement.body, category: announcement.category },
      }).catch(() => {});

      toast.success(`Announcement archived.`, { id: toastAttempt });
      router.refresh();

    } catch {
      toast.warning('The action could not be confirmed. Refresh the record before trying again.', { id: toastAttempt });
    }
  }

  const meta = ANNOUNCEMENT_CATEGORY_META[announcement.category as keyof typeof ANNOUNCEMENT_CATEGORY_META];

  return (
    <>
    <ContentEditDialog open={isEditing} title="Edit announcement" context={announcement.title}
      description="Update the content, category, and optional image shown to residents." busy={submitting} onClose={() => setIsEditing(false)}>
      <form
        onSubmit={handleSave}
        className={editStyles.form} aria-busy={submitting}>
        <div className={editStyles.fields} data-edit-scroll>
        <fieldset disabled={submitting}>
          <div className={editStyles.grid}>
            <label className={editStyles.full}>
              <span className={labelClass}>Title</span>
              <input className={inputClass} value={title} onChange={(e) => setTitle(e.target.value)} required />
            </label>

            <label className="text-sm">
              <span className={labelClass}>Category</span>
              <AdminSelect kind="announcement" className={inputClass} value={category} onValueChange={(nextValue) => setCategory(nextValue)}>
                {ANNOUNCEMENT_CATEGORIES.map((cat) => (
                  <option key={cat} value={cat}>
                    {ANNOUNCEMENT_CATEGORY_META[cat].label}
                  </option>
                ))}
              </AdminSelect>
            </label>

            <label className="text-sm">
              <span className={labelClass}>Image URL (optional)</span>
              <input
                className={inputClass}
                value={imageUrl}
                onChange={(e) => setImageUrl(e.target.value)}
                placeholder="https://…"
                type="url"
              />
            </label>

            <label className={editStyles.full}>
              <span className={labelClass}>Body</span>
              <textarea
                className={inputClass}
                value={body}
                onChange={(e) => setBody(e.target.value)}
                rows={3}
                required
              />
            </label>

            <label className={editStyles.full}>
              <span className={labelClass}>Detailed Description (optional)</span>
              <textarea
                className={inputClass}
                value={detailedDescription}
                onChange={(e) => setDetailedDescription(e.target.value)}
                rows={4}
                placeholder="Full write-up shown when a resident taps the announcement for more detail…"
              />
            </label>

            {error ? <p role="alert" className={`${editStyles.full} ${editStyles.error}`}>{error}</p> : null}

          </div>
        </fieldset>
        </div>
        <div className={editStyles.actions}>
          <button
            type="button"
            onClick={() => setIsEditing(false)}
            disabled={submitting}>
            Cancel
          </button>
          <button
            type="submit"
            disabled={submitting}
            aria-busy={submitting}>
            <LoadingButtonContent pending={submitting} pendingLabel="Saving…">Save Changes</LoadingButtonContent>
          </button>
        </div>
      </form>
    </ContentEditDialog>
    <div className={styles.row}>
      <div className={styles.rowHeader}>
        <div className={styles.rowMain}>
          <div className="flex flex-wrap items-center gap-2">
            {/* Category color dot + badge */}
            <span
              className="inline-block h-2.5 w-2.5 shrink-0 rounded-full"
              style={{ backgroundColor: meta?.color }}
            />
            <span
              className={`${styles.badge} ${announcement.category === 'emergency' ? styles.urgentStatus : ''}`}>
              {meta?.label}
            </span>
            <h3 className={styles.rowTitle}>{announcement.title}</h3>
          </div>
          <p className={styles.rowMeta}>{formatPublishedAt(announcement.published_at)}</p>
        </div>

      </div>

      <div className={styles.rowDescription}>
        <p className="line-clamp-2">{announcement.body}</p>
      </div>
      <div className={`${styles.rowActions} mt-4`}>
        <button type="button" onClick={startEdit} aria-haspopup="dialog" aria-label={`Edit ${announcement.title}`}
          className={styles.primaryAction}>Edit announcement</button>
        <ConfirmButton label="Archive" ariaLabel={`Archive ${announcement.title}`}
          confirmLabel="Archive?" onConfirm={archive} className={styles.dangerAction} />
      </div>
    </div>
    </>
  );
}<!-- BEGIN:nextjs-agent-rules -->

