import { announcementSchema } from './announcement';

describe('announcementSchema', () => {
  it('parses a valid announcement', () => {
    const result = announcementSchema.safeParse({
      title: 'Road Closure Notice',
      body: 'Main street will be closed for repairs.',
      category: 'general',
    });
    expect(result.success).toBe(true);
  });

  it('rejects a missing title', () => {
    const result = announcementSchema.safeParse({
      title: '',
      body: 'Body text',
      category: 'general',
    });
    expect(result.success).toBe(false);
  });

  it('rejects a missing body', () => {
    const result = announcementSchema.safeParse({
      title: 'Title',
      body: '',
      category: 'general',
    });
    expect(result.success).toBe(false);
  });

  it('rejects an invalid category', () => {
    const result = announcementSchema.safeParse({
      title: 'Title',
      body: 'Body',
      category: 'not-a-real-category',
    });
    expect(result.success).toBe(false);
  });

  it('rejects an invalid image_url', () => {
    const result = announcementSchema.safeParse({
      title: 'Title',
      body: 'Body',
      category: 'general',
      image_url: 'not-a-url',
    });
    expect(result.success).toBe(false);
  });

  it('accepts an empty string image_url', () => {
    const result = announcementSchema.safeParse({
      title: 'Title',
      body: 'Body',
      category: 'general',
      image_url: '',
    });
    expect(result.success).toBe(true);
  });

  it('accepts a missing detailed_description', () => {
    const result = announcementSchema.safeParse({
      title: 'Title',
      body: 'Body',
      category: 'general',
    });
    expect(result.success).toBe(true);
  });

  it('accepts a valid detailed_description', () => {
    const result = announcementSchema.safeParse({
      title: 'Title',
      body: 'Body',
      category: 'general',
      detailed_description: 'A much longer write-up with the full context residents need.',
    });
    expect(result.success).toBe(true);
  });

  it('rejects a detailed_description over 5000 characters', () => {
    const result = announcementSchema.safeParse({
      title: 'Title',
      body: 'Body',
      category: 'general',
      detailed_description: 'a'.repeat(5001),
    });
    expect(result.success).toBe(false);
  });
});import { z } from 'zod';

export const announcementSchema = z.object({
  title:                z.string().min(1, 'Title is required').max(200),
  body:                 z.string().min(1, 'Body is required').max(2000),
  // Expanded write-up shown in the resident app's Announcement Modal. Optional — falls
  // back to `body` in the UI when omitted.
  detailed_description: z.string().max(5000, 'Detailed description is too long').optional().or(z.literal('')),
  category:             z.enum(['general', 'emergency', 'health', 'events']),
  image_url:            z.string().url('Must be a valid URL').optional().or(z.literal('')),
  published_at:         z.string().datetime().optional(), // ISO string; defaults to now() on insert
});

export type AnnouncementFormValues = z.infer<typeof announcementSchema>;-- Adds: (1) soft-delete column on announcements so archived items stay in the DB but
-- disappear from resident/guest feeds; (2) admin write RLS on announcements; (3) rebuilt
-- SELECT policies that filter out soft-deleted rows.
--
-- Pattern mirrors 0009's admin CRUD on document_types / service_requests.

-- ============================================================================
-- soft-delete column
-- ============================================================================
alter table public.announcements
  add column if not exists deleted_at timestamptz;

-- ============================================================================
-- SELECT policies — drop and recreate to add deleted_at IS NULL guard.
-- Original policies were created in 0003 / 0005 migrations.
-- ============================================================================
drop policy if exists "residents can read announcements from their barangay" on public.announcements;
drop policy if exists "guests can read all announcements"                    on public.announcements;

create policy "residents can read announcements from their barangay"
  on public.announcements for select
  to authenticated
  using (barangay_id = public.current_barangay_id() and deleted_at is null);

create policy "guests can read all announcements"
  on public.announcements for select
  to anon
  using (deleted_at is null);

-- ============================================================================
-- Admin ALL policy — insert / update / delete (soft) scoped to own barangay.
-- ============================================================================
create policy "admins can manage announcements in their barangay"
  on public.announcements for all
  to authenticated
  using  (barangay_id = public.current_barangay_id() and public.current_role() = 'admin')
  with check (barangay_id = public.current_barangay_id() and public.current_role() = 'admin');-- S0-5 / P1-C: migrations 0003 and 0005 created SELECT policies on announcements
-- ("residents can read their own barangay's announcements", "anyone can read
-- announcements") without a deleted_at IS NULL check. Migration 0011 tried to drop
-- policies by different names ("residents can read announcements from their barangay",
-- "guests can read all announcements") — a no-op against the originals — and created its
-- own corrected policies (which DO filter deleted_at IS NULL) alongside them. Result: 4
-- active SELECT policies, 2 without the soft-delete filter, so deleted announcements
-- remained visible. This drops the two original, unfiltered policies by their actual
-- names; the corrected 0011 policies remain active.
drop policy if exists "residents can read their own barangay's announcements" on public.announcements;
drop policy if exists "anyone can read announcements" on public.announcements;
